svg.script:
function getSVGCoords(evt, svgElement) {
    var rect = svgElement.getBoundingClientRect();
    var scaleX = svgElement.viewBox.baseVal.width / rect.width;
    var scaleY = svgElement.viewBox.baseVal.height / rect.height;

    return {
        x: (evt.clientX - rect.left) * scaleX,
        y: (evt.clientY - rect.top) * scaleY
    };
}
function showTooltip(evt, groupId) {
    var svgElement = evt.target.ownerSVGElement || evt.target;
    var tooltip = document.querySelector(`#${groupId} text`);

    if (tooltip) {
        var coords = getSVGCoords(evt, svgElement);
        var rect = svgElement.getBoundingClientRect();

        // Default offset
        let xOffset = 10;  
        let yOffset = -10; 

        // If tooltip is too far right, shift left
        if (coords.x + 100 > rect.width) { 
            xOffset = -100; 
        }

        tooltip.setAttribute("visibility", "visible");
        tooltip.setAttribute("x", coords.x + xOffset);
        tooltip.setAttribute("y", coords.y + yOffset);

        tooltip.querySelectorAll("tspan").forEach((tspan, index) => {
            tspan.setAttribute("x", coords.x + xOffset);
            if (index === 0) {
                tspan.setAttribute("y", coords.y + yOffset);
            } else {
                tspan.setAttribute("dy", "1.2em");
            }
        });
    }
}

function moveTooltip(evt, groupId) {
    var svgElement = evt.target.ownerSVGElement || evt.target;
    var tooltip = document.querySelector(`#${groupId} text`);

    if (tooltip) {
        var coords = getSVGCoords(evt, svgElement);
        var rect = svgElement.getBoundingClientRect();

        // Default offset
        let xOffset = 10;  
        let yOffset = -10; 

        // If tooltip is too far right, shift left
        if (coords.x + 100 > rect.width) { 
            xOffset = -100; 
        }

        tooltip.setAttribute("x", coords.x + xOffset);
        tooltip.setAttribute("y", coords.y + yOffset);

        tooltip.querySelectorAll("tspan").forEach((tspan, index) => {
            tspan.setAttribute("x", coords.x + xOffset);
            if (index === 0) {
                tspan.setAttribute("y", coords.y + yOffset);
            } else {
                tspan.setAttribute("dy", "1.2em");
            }
        });
    }
}

let isActive = false;
let isHovered = false;

function highlightEdge(isHovering, element) {
    isHovered = isHovering;
    element.classList.toggle("hover", isHovered);
    console.log("Hover Event:", isHovered, "Element:", element);
}

function toggleEdge(element) {
    isActive = !isActive;
    element.classList.toggle("active", isActive);
    console.log("Toggle Edge Active:", isActive, "Element:", element);
}

window.addEventListener('resize', handleZoom);
window.addEventListener('wheel', handleZoom);

function handleZoom(event) {
    if (event.ctrlKey || event.metaKey || event.scale !== 1) return;
}

function resetEdgeState() {
    let edges = document.getElementsByClassName("edge");
    let clickable = document.getElementById("clickable");
    isActive = false;
    isHovered = false;

    for (let edge of edges) {
        edge.classList.remove("active", "hover");
    }

    if (clickable) clickable.setAttribute("stroke", "transparent");
}

document.addEventListener('click', (event) => {
    let edges = document.getElementsByClassName("edge");
    let isInside = Array.from(edges).some(edge => edge.contains(event.target));
    if (!isInside) resetEdgeState();
});
